// Built to Perform — Plan B (#built-to-perform-b): left tab rail + Search Index bubble chart
// (labels, hover tooltip, resize redraw). Loaded synchronously by src/sections/07-showcase/built-to-perform-b.html.
    (function initBuiltToPerformTabsB() {
      const ENABLE_TAB_SWITCHING = true;

      // 1. Interactive Bubble Chart Implementation (Search API Quality, Cost & Latency)
      function initBubbleChartB() {
        const root = document.getElementById('built-to-perform-b');
        if (!root) return null;
        const wrapper = root.querySelector('.built-perf-bubble-wrapper');
        const svg = root.querySelector('svg.bubble-plot');
        const tip = root.querySelector('.bubble-tip');
        if (!wrapper || !svg || !tip) return null;

        const ROWS = [
          ["Perplexity Search (medium)", 80, 62.30, 8.04, 26.6, 13.5, 13.1, null, "r"],
          ["Perplexity Search (high)", 79, 56.93, 9.72, 27.3, 12.7, 14.6, null, "r!"],
          ["Octen Search (highlights)", 77, 9.07, 14.92, 15.0, 1.90, 13.1, "#039855", "tl"],
          ["Parallel Search (advanced)", 75, 47.93, 11.29, 40.4, 25.5, 14.9, null, "t"],
          ["Brave Search (LLM context)", 75, 61.96, 17.46, 21.6, 5.29, 16.3, null, "r"],
          ["OpenAI Web Search (medium)", 74, 40.19, 9.40, 29.8, 20.1, 9.68, null, "tl"],
          ["You.com Search (highlights)", 74, 47.54, 19.58, 18.7, 6.67, 12.0, null, "tr"],
          ["Nimble Search (standard)", 74, 46.14, 19.57, 40.0, 8.97, 31.0, null, "bl"],
          ["Exa Search (auto)", 74, 65.57, 17.73, 30.7, 15.6, 15.2, null, "r"],
          ["Firecrawl Search", 73, 30.48, 12.09, 60.3, 42.8, 17.5, null, "b"],
          ["Parallel Search (basic)", 73, 45.14, 21.65, 25.2, 9.23, 16.0, null, "r"],
          ["TinyFish Search (web)", 71, 0, 9.30, 56.8, 35.2, 21.6, null, "b"],
        ];

        const OCTEN_MARK = "data:image/svg+xml;base64,";
        const LOGOS = {
  brave: "data:image/svg+xml;base64,",
  exa: "data:image/svg+xml;base64,",
  firecrawl: "data:image/svg+xml;base64,",
  nimble: "data:image/svg+xml;base64,",
  octen: "data:image/svg+xml;base64,",
  openai: "data:image/svg+xml;base64,",
  parallel: "data:image/svg+xml;base64,",
  perplexity: "data:image/svg+xml;base64,",
  tinyfish: "data:image/svg+xml;base64,",
  youcom: "data:image/svg+xml;base64,",
};

        const logoOf = name => LOGOS[name.split(" ")[0].toLowerCase().replace(".", "")];
        const secs = v => (v < 10 ? v.toFixed(2) : v.toFixed(1)) + "s";

        const M = { l: 54, r: 14, t: 14, b: 40 };
        const X = { min: 0, max: 0.1, step: 0.01 }, Y = { min: 70, max: 82, step: 2 };
        const QUAD = { x: 0.05, y: 76 };

        let W = 720, H = 360;
        let sx = v => M.l + (v - X.min) / (X.max - X.min) * (W - M.l - M.r);
        let sy = v => H - M.b - (v - Y.min) / (Y.max - Y.min) * (H - M.t - M.b);
        const radius = t => 1.55 * Math.sqrt(t);

        let bubbles = [];
        let current = null;

        function highlight(c, on) {
          if (!c) return;
          c.classList.toggle("hot", on);
          if (c._p && c._p.label) c._p.label.classList.toggle("hot", on);
        }

        function hide() {
          highlight(current, false);
          current = null;
          tip.classList.remove("is-visible");  // a class, not inline opacity: navbar.css forces [style*="opacity: 0"] to opacity 1
          svg.style.cursor = "";
        }

        function render(c) {
          if (current === c) return;
          highlight(current, false);
          current = c;
          highlight(c, true);
          const p = c._p;
          const seg = p.name.startsWith("Octen") ? p.color : "#EC6D51";
          const modelSeg = "var(--model-seg, #dcdbd4)";
          // Shared time scale: the slowest product fills the bar, every other bar is proportionally shorter
          const T_MAX = Math.max(...ROWS.map(r => r[4]));
          const T_MIN = Math.min(...ROWS.map(r => r[4]));  // the fastest product gets a "Fastest" badge
          const pct = v => `calc(${(v / T_MAX * 100).toFixed(2)}% - 1px)`;
          tip.innerHTML = `
            <div class="tip-head"><img class="tip-logo" src="${logoOf(p.name)}" alt="">${p.name.replace(/ (Web )?Search/, "")}</div>
            <hr>
            <div class="tip-row"><span>Search Index:</span><b>${p.score}</b></div>
            <div class="tip-row"><span>Cost per Task:</span><b>$${p.cost.toFixed(4)}</b></div>
            <hr>
            <div class="tip-row"><span>Time per Task:${p.t === T_MIN ? '<i class="tip-badge">Fastest</i>' : ""}</span><b>${secs(p.t)}</b></div>
            <div class="tip-bar"><i style="width:${pct(p.ts)};background:${seg}"></i><i style="width:${pct(p.tm)};background:${modelSeg}"></i></div>
            <div class="tip-keys"><span style="--c:${seg}">Search: ${secs(p.ts)}</span><span style="--c:${modelSeg}">Model: ${secs(p.tm)}</span></div>`;
        }

        function place(x, y) {
          const w = wrapper.clientWidth, h = wrapper.clientHeight, gap = 16;
          let left = x + gap, top = y - tip.offsetHeight / 2;
          if (left + tip.offsetWidth > w) left = x - gap - tip.offsetWidth;
          tip.style.left = Math.max(0, left) + "px";
          tip.style.top = Math.min(Math.max(0, top), h - tip.offsetHeight) + "px";
          tip.classList.add("is-visible");
        }

        function draw() {
          while (svg.firstChild) svg.removeChild(svg.firstChild);

          const rect = wrapper.getBoundingClientRect();
          W = rect.width > 50 ? rect.width : (wrapper.clientWidth || 720);
          H = rect.height > 50 ? rect.height : (wrapper.clientHeight || 360);
          svg.setAttribute("viewBox", `0 0 ${W} ${H}`);

          sx = v => M.l + (v - X.min) / (X.max - X.min) * (W - M.l - M.r);
          sy = v => H - M.b - (v - Y.min) / (Y.max - Y.min) * (H - M.t - M.b);

          const pts = ROWS.map(([name, score, s, m, t, ts, tm, color, pos]) => ({
            name, score, cost: (s + m) / 1000, search: s / 1000, model: m / 1000, t, ts, tm, color, pos, r: radius(t),
          }));

          const grays = pts.filter(p => !p.color), ts = grays.map(p => p.t);
          const lo = Math.min(...ts), hi = Math.max(...ts);
          // 灰色的圆：耗时越短颜色越深(DARK)，耗时越长灰色越浅(LIGHT)
          const LIGHT = [0xC8, 0xC7, 0xC0], DARK = [0x50, 0x50, 0x4D];
          for (const p of grays) {
            const k = (p.t - lo) / (hi - lo);
            p.color = "#" + DARK.map((c, i) => Math.round(c + (LIGHT[i] - c) * k).toString(16).padStart(2, "0")).join("");
          }

          const NS = "http://www.w3.org/2000/svg";
          const el = (tag, attrs, parent = svg) => {
            const n = document.createElementNS(NS, tag);
            for (const k in attrs) n.setAttribute(k, attrs[k]);
            parent.appendChild(n);
            return n;
          };
          const text = (str, attrs) => { const n = el("text", attrs); n.textContent = str; return n; };

          // Quadrants
          el("rect", { x: sx(X.min), y: sy(Y.max), width: sx(QUAD.x) - sx(X.min), height: sy(QUAD.y) - sy(Y.max), fill: "#CAEBC5", "fill-opacity": "0.32", stroke: "rgba(120, 210, 110, 0.4)", "stroke-width": "1" });
          el("rect", { x: sx(QUAD.x), y: sy(QUAD.y), width: sx(X.max) - sx(QUAD.x), height: sy(Y.min) - sy(QUAD.y), fill: "rgba(0, 0, 0, 0.02)" });

          // Gridlines
          for (let v = Y.min + Y.step; v <= Y.max; v += Y.step) {
            el("line", { x1: sx(X.min), y1: sy(v), x2: sx(X.max), y2: sy(v), stroke: "#F1F5F9", "stroke-width": "1" });
          }

          // Axes
          el("line", { x1: sx(X.min), y1: sy(Y.min), x2: sx(X.max), y2: sy(Y.min), stroke: "#CBD5E1", "stroke-width": "1" });
          el("line", { x1: sx(X.min), y1: sy(Y.min), x2: sx(X.min), y2: sy(Y.max), stroke: "#CBD5E1", "stroke-width": "1" });

          // Ticks
          for (let v = X.min; v <= X.max + 1e-9; v += X.step) {
            el("line", { x1: sx(v), y1: sy(Y.min), x2: sx(v), y2: sy(Y.min) + 6, stroke: "#CBD5E1" });
            text("$" + +v.toFixed(2), { x: sx(v), y: sy(Y.min) + 18, class: "tick", "text-anchor": "middle" });
          }
          for (let v = Y.min; v <= Y.max; v += Y.step) {
            el("line", { x1: sx(X.min) - 6, y1: sy(v), x2: sx(X.min), y2: sy(v), stroke: "#CBD5E1" });
            text(v, { x: sx(X.min) - 12, y: sy(v), class: "tick", "text-anchor": "end", "dominant-baseline": "middle" });
          }

          // Axis titles
          text("Cost per Task (USD)", { x: (sx(X.min) + sx(X.max)) / 2, y: H - 4, class: "axis-title", "text-anchor": "middle" });
          text("Artificial Analysis Search Index", { x: 0, y: 0, class: "axis-title", "text-anchor": "middle",
            transform: `translate(12 ${(sy(Y.min) + sy(Y.max)) / 2}) rotate(-90)` });

          const obstacles = [];

          // Pareto line
          let bestScore = -Infinity;
          const pareto = [...pts].sort((a, b) => a.cost - b.cost).filter(p => p.score > bestScore && (bestScore = p.score, true));
          el("polyline", { points: pareto.map(p => `${sx(p.cost)},${sy(p.score)}`).join(" "), fill: "none",
            stroke: "#555555", "stroke-width": "2.5", "stroke-dasharray": "1 5", "stroke-linecap": "round" });

          // Bubbles
          bubbles = [...pts].sort((a, b) => b.r - a.r).map(p => {
            const c = el("circle", { cx: sx(p.cost), cy: sy(p.score), r: p.r, fill: p.color, class: "bubble", tabindex: 0 });
            c.setAttribute("aria-label", `${p.name}: index ${p.score}, $${p.cost.toFixed(4)} per task, ${p.t}s per task`);
            c._p = p;
            return c;
          });
          pts.forEach(p => obstacles.push({ x: sx(p.cost), y: sy(p.score), r: p.r + 2, name: p.name }));

          // Label placement algorithm with collision detection
          const SLOTS = {
            r:  (x, y, r) => [x + r + 6, y, "start"],
            l:  (x, y, r) => [x - r - 6, y, "end"],
            t:  (x, y, r) => [x, y - r - 10, "middle"],
            b:  (x, y, r) => [x, y + r + 12, "middle"],
            tl: (x, y, r) => [x - r * 0.4, y - r - 9, "end"],
            tr: (x, y, r) => [x + r * 0.4, y - r - 9, "start"],
            bl: (x, y, r) => [x - r * 0.4, y + r + 11, "end"],
            br: (x, y, r) => [x + r * 0.4, y + r + 11, "start"],
            tr2: (x, y, r) => [x + r * 0.8, y - r - 4, "start"],
            tl2: (x, y, r) => [x - r * 0.8, y - r - 4, "end"],
            br2: (x, y, r) => [x + r * 0.4, y + r + 8, "start"],
            bl2: (x, y, r) => [x - r * 0.4, y + r + 8, "end"],
          };
          for (const d of [22, 36, 50]) Object.assign(SLOTS, {
            ["fbr" + d]: (x, y, r) => [x + r * 0.5 + d * 0.5, y + r + d, "start", true],
            ["fbl" + d]: (x, y, r) => [x - r * 0.5 - d * 0.5, y + r + d, "end", true],
            ["ftr" + d]: (x, y, r) => [x + r * 0.5 + d * 0.5, y - r - d, "start", true],
            ["ftl" + d]: (x, y, r) => [x - r * 0.5 - d * 0.5, y - r - d, "end", true],
          });
          const boxHitsCircle = (b, c) => {
            const dx = Math.max(b.x - c.x, 0, c.x - (b.x + b.width));
            const dy = Math.max(b.y - c.y, 0, c.y - (b.y + b.height));
            return dx * dx + dy * dy < c.r * c.r;
          };
          const boxesOverlap = (a, b) => a.x < b.x + b.width && b.x < a.x + a.width && a.y < b.y + b.height && b.y < a.y + a.height;
          const inPlot = b => b.x >= M.l + 2 && b.x + b.width <= W && b.y >= 0 && b.y + b.height <= sy(Y.min) - 2;

          const MARK = { w: 18, h: 15, gap: 4 };
          const placed = [];
          for (const p of pts) {
            const hero = p.name.startsWith("Octen");
            const cx = sx(p.cost), cy = sy(p.score);
            const node = text(p.name.replace(/ (Web )?Search/, ""), { class: hero ? "lbl hero" : "lbl", "dominant-baseline": "middle" });

            if (hero) {
              node.setAttribute("text-anchor", "start");
              node.setAttribute("dominant-baseline", "middle");
              let textW = 108;
              try {
                const tb = node.getBBox();
                if (tb && tb.width > 20) textW = tb.width;
              } catch(e) {}

              const totalW = MARK.w + MARK.gap + textW;
              const startX = cx - totalW / 2;
              const textY = cy - p.r - 10;

              node.setAttribute("x", startX + MARK.w + MARK.gap);
              node.setAttribute("y", textY);

              const g = el("g", { class: "lbl-hero" });
              svg.insertBefore(g, node);

              el("image", {
                href: OCTEN_MARK,
                x: startX,
                y: textY - MARK.h / 2,
                width: MARK.w,
                height: MARK.h
              }, g);

              g.appendChild(node);
              p.label = g;

              placed.push({
                x: startX - 2,
                y: textY - MARK.h / 2 - 2,
                width: totalW + 4,
                height: Math.max(MARK.h, 16) + 4
              });
              continue;
            }

            // A trailing "!" pins the label to that slot and skips collision fallback
            const pinned = p.pos.endsWith("!"), pos = pinned ? p.pos.slice(0, -1) : p.pos;
            const order = pinned ? [pos] : [pos, ...Object.keys(SLOTS).filter(s => s !== pos)];
            let leader = null;
            const put = s => {
              const [x, y, anchor, far] = SLOTS[s](cx, cy, p.r);
              leader = far ? { x: anchor === "start" ? x - 3 : x + 3, y } : null;
              node.setAttribute("x", x);
              node.setAttribute("y", y);
              node.setAttribute("text-anchor", anchor);
              let b;
              try { b = node.getBBox(); } catch(err) { b = { x: x, y: y - 6, width: 70, height: 13 }; }
              return { x: b.x - 2, y: b.y - 1, width: b.width + 4, height: b.height + 2 };
            };
            let box = null;
            for (const s of order) {
              const b = put(s);
              if (pinned || (inPlot(b) && !placed.some(q => boxesOverlap(b, q)) && !obstacles.some(c => c.name !== p.name && boxHitsCircle(b, c)))) { box = b; break; }
            }
            placed.push(box || put(pos));
            p.label = node;
            if (box && leader) {
              const dx = leader.x - cx, dy = leader.y - cy, len = Math.hypot(dx, dy);
              el("line", { x1: cx + dx / len * (p.r + 2), y1: cy + dy / len * (p.r + 2), x2: leader.x, y2: leader.y,
                stroke: "#94A3B8", "stroke-width": 1 }, svg).parentNode.insertBefore(svg.lastChild, node);
            }
          }

          bubbles.forEach(c => {
            c.addEventListener("focus", () => {
              render(c);
              place(sx(c._p.cost) + c._p.r, sy(c._p.score));
            });
            c.addEventListener("blur", hide);
          });
        }

        // Mouse: follows cursor with HOVER_PAD px proximity
        const HOVER_PAD = 14;
        svg.addEventListener("mousemove", e => {
          const r = svg.getBoundingClientRect(), mx = e.clientX - r.left, my = e.clientY - r.top;
          let best = null, bestGap = Infinity;
          for (const c of bubbles) {
            const p = c._p;
            if (!p) continue;
            const gapToEdge = Math.hypot(mx - sx(p.cost), my - sy(p.score)) - p.r;
            if (gapToEdge <= HOVER_PAD && gapToEdge < bestGap) {
              best = c;
              bestGap = gapToEdge;
            }
          }
          if (!best) return hide();
          svg.style.cursor = "pointer";
          render(best);
          place(mx, my);
        });

        svg.addEventListener("mouseleave", hide);

        draw();
        if (document.fonts && document.fonts.ready) {
          document.fonts.ready.then(draw);
        }

        let resizeTimer = null;
        window.addEventListener("resize", () => {
          clearTimeout(resizeTimer);
          resizeTimer = setTimeout(draw, 100);
        }, { passive: true });

        return { redraw: draw };
      }

      function setup() {
        const bubbleChart = initBubbleChartB();

        const container = document.getElementById('perfTabsList-b');
        if (!container || container.dataset.bound === 'true') return;
        container.dataset.bound = 'true';

        const tabs = container.querySelectorAll('.built-perf-item');
        const chartCost = document.getElementById('chartCostEfficiency-b');
        const chartAcc = document.getElementById('chartAccuracy-b');
        const bar = document.getElementById('perfRailBar-b');
        const dot = document.getElementById('perfRailDot-b');

        function updateRail() {
          const activeItem = container.querySelector('.built-perf-item.active');
          if (!activeItem || !bar || !dot) return;

          const containerRect = container.getBoundingClientRect();
          const itemRect = activeItem.getBoundingClientRect();
          const label = activeItem.querySelector('.built-perf-label');
          const labelRect = label ? label.getBoundingClientRect() : itemRect;

          const dotTop = (labelRect.top - containerRect.top) + (labelRect.height / 2) - 6.5;
          const itemTop = itemRect.top - containerRect.top;
          const itemHeight = itemRect.height;

          dot.style.top = `${dotTop}px`;
          bar.style.top = `${itemTop}px`;
          bar.style.height = `${itemHeight}px`;
        }

        requestAnimationFrame(() => {
          updateRail();
          setTimeout(updateRail, 150);
        });
        window.addEventListener('resize', updateRail, { passive: true });

        tabs.forEach(tab => {
          tab.addEventListener('click', () => {
            if (!ENABLE_TAB_SWITCHING) return;

            const key = tab.dataset.perfTab;
            tabs.forEach(t => {
              const isTarget = t === tab;
              const body = t.querySelector('.built-perf-body');

              if (isTarget) {
                t.classList.add('active');
                if (body) {
                  body.style.display = 'block';
                  body.style.opacity = '1';
                  body.style.height = 'auto';
                }
              } else {
                t.classList.remove('active');
                if (body) {
                  body.style.display = 'none';
                  body.style.opacity = '0';
                  body.style.height = '0';
                }
              }
            });

            // Toggle right-hand benchmark panels
            if (chartCost && chartAcc) {
              if (key === 'accuracy') {
                chartCost.style.display = 'none';
                chartAcc.style.display = 'block';
              } else {
                chartAcc.style.display = 'none';
                chartCost.style.display = 'block';
                if (bubbleChart && bubbleChart.redraw) {
                  requestAnimationFrame(bubbleChart.redraw);
                }
              }
            }

            requestAnimationFrame(updateRail);
          });
        });
      }

      if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', setup);
      } else {
        setup();
      }
    })();
